                  seen.add(q); stack.append(q)
          comps.append(comp)
    # The requested pattern is the isolated object in the lower-left region.
    comp=min(comps, key=lambda z: (-max(y for y,x in z), min(x for y,x in z)))
    r0=min(y for y,x in comp); r1=max(y for y,x in comp); c0=min(x for y,x in comp); c1=max(x for y,x in comp)
    return [[grid[r][c] if (r,c) in set(comp) else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
'''
